 9 │ /** Persists exact PackageManager overrides before disabling components. RecoveryActivity is the marker. */
10 │ internal class RecoveryComponents(private val context: Context) {
11 │     private val manager = context.packageManager
12 │     private val recovery = ComponentName(context, RecoveryActivity::class.java)
13 │     private val snapshot = PrivateSettingsFile(File(context.noBackupFilesDir, "component_states_v1"))
14 │     fun isRecovering() = manager.getComponentEnabledSetting(recovery) == PackageManager.COMPONENT_ENABLED_STATE_ENABLED
15 │ 
16 │     @Suppress("DEPRECATION")
17 │     fun block(): Boolean {
18 │         if (!isRecovering()) manager.setComponentEnabledSetting(recovery, PackageManager.COMPONENT_ENABLED_STATE_ENABLED, PackageManager.DONT_KILL_APP)
19 │         val packageInfo = manager.getPackageInfo(context.packageName, PackageManager.GET_ACTIVITIES or
20 │             PackageManager.GET_SERVICES or PackageManager.GET_RECEIVERS or PackageManager.GET_PROVIDERS or PackageManager.GET_DISABLED_COMPONENTS)
21 │         val components = (packageInfo.activities.orEmpty().toList() + packageInfo.services.orEmpty().toList() +
22 │             packageInfo.receivers.orEmpty().toList() + packageInfo.providers.orEmpty().toList())
23 │             .filter { it.name != recovery.className }.distinctBy { it.name }
24 │         val states = snapshot.read()?.toMutableMap() ?: linkedMapOf()
25 │         validate(states)
26 │         var extended = false
27 │         for (component in components) if (component.name !in states) {
28 │             states[component.name] = manager.getComponentEnabledSetting(ComponentName(context.packageName, component.name)).toString()
29 │             extended = true
30 │         }
31 │         if (extended) snapshot.write(states)
32 │         var changed = false
33 │         for (component in components) {
34 │             val name = ComponentName(context.packageName, component.name)
35 │             val state = manager.getComponentEnabledSetting(name)
36 │             // Components whose manifest is disabled are already stopped when their raw state is DEFAULT.
37 │             val enabled = state == PackageManager.COMPONENT_ENABLED_STATE_ENABLED ||
38 │                 state == PackageManager.COMPONENT_ENABLED_STATE_DEFAULT && component.enabled
39 │             if (enabled) {
40 │                 manager.setComponentEnabledSetting(name, PackageManager.COMPONENT_ENABLED_STATE_DISABLED, PackageManager.DONT_KILL_APP)
41 │                 changed = true
42 │             }
43 │         }
44 │         return changed
45 │     }
46 │     fun heal() {
47 │         if (!isRecovering()) return
48 │         snapshot.read()?.let { states ->
49 │             validate(states)
50 │             states.forEach { (name, raw) ->
51 │                 val component = ComponentName(context.packageName, name)
52 │                 val expected = raw.toInt()
53 │                 if (manager.getComponentEnabledSetting(component) != expected)
54 │                     manager.setComponentEnabledSetting(component, expected, PackageManager.DONT_KILL_APP)
55 │             }
56 │             snapshot.clear()
57 │         }
58 │         manager.setComponentEnabledSetting(recovery, PackageManager.COMPONENT_ENABLED_STATE_DISABLED, PackageManager.DONT_KILL_APP)
59 │     }
60 │     private fun validate(states: Map<String, String>) {
61 │         require(states.keys.none { it == recovery.className || !it.contains('.') })
62 │         states.values.forEach { require(it.toInt() in 0..4) }
63 │     }
64 │ }
