69 │ internal class AndroidSqlTransactions(private val open: () -> SupportSQLiteDatabase) : SqlTransactionRunner {
70 │     override fun <T> inTransaction(block: (SqlSession) -> T): T {
71 │         val database = open()
72 │         database.beginTransaction()
73 │         try {
74 │             val result = block(object : SqlSession {
75 │                 override fun query(sql: String, args: List<Any?>): List<List<Any?>> = database.query(sql, args.toTypedArray()).use { cursor ->
76 │                     buildList {
77 │                         while (cursor.moveToNext()) add((0 until cursor.columnCount).map { index ->
78 │                             when (cursor.getType(index)) {
79 │                                 android.database.Cursor.FIELD_TYPE_NULL -> null
80 │                                 android.database.Cursor.FIELD_TYPE_INTEGER -> cursor.getLong(index)
81 │                                 android.database.Cursor.FIELD_TYPE_STRING -> cursor.getString(index)
82 │                                 else -> error("Unexpected configuration column type")
83 │                             }
84 │                         })
85 │                     }
86 │                 }
87 │                 override fun execute(sql: String, args: List<Any?>) = database.execSQL(sql, args.toTypedArray())
88 │             })
89 │             database.setTransactionSuccessful()
90 │             return result
91 │         } finally { database.endTransaction() }
92 │     }
