 55 │  * pre-existing value in the main DataStore is merged, never copied through as is [SnapshotAssemblerTest].
 56 │  */
 57 │ class SnapshotAssembler(private val widgets: WidgetProfilePort, private val widgetKey: String) {
 58 │     class Rejected : RuntimeException("widget profiles are malformed")
 59 │ 
 60 │     fun assemble(
 61 │         source: PortableSource,
 62 │         preferencesXml: String,
 63 │         mainDataStore: Map<String, SettingValue>,
 64 │         widgetStates: List<Map<String, SettingValue>>,
 65 │         rows: ConfigurationRows,
 66 │     ): LegacySourceSnapshot {
 67 │         val existing = when (val value = mainDataStore[widgetKey]) {
 68 │             null -> null
 69 │             is SettingValue.Text -> value.value
 70 │             else -> throw Rejected()
 71 │         }
 72 │         val encoded = try {
 73 │             widgets.encodedProfiles(widgetStates, existing)
 74 │         } catch (failure: Exception) {
 75 │             throw Rejected()
 76 │         }
 77 │         val dataStore = mainDataStore - widgetKey + (if (encoded != null) mapOf(widgetKey to SettingValue.Text(encoded)) else emptyMap())
 78 │         return LegacySourceSnapshot(source, preferencesXml, dataStore, rows)
 79 │     }
 80 │ }
 81 │ 
 82 │ /**
 83 │  * Last gate before a file may be offered to the Storage Access Framework.
 84 │  *
 85 │  * CLAIM(self-decode): the bytes are decoded by the shared codec under default limits, re-encode to the same bytes,
 86 │  * pass the semantic validator, and contain only catalog Configuration keys of the catalog's type; anything else is
 87 │  * [ConversionFailure.SELF_CHECK_FAILED] and no file exists [PortableFileSealerTest].
 88 │  */
 89 │ object PortableFileSealer {
 90 │     fun seal(
 91 │         ready: PortableSettingsResult.Ready,
 92 │         validator: SemanticValidator,
 93 │         widgetProfileCount: Int,
 94 │         versionKnown: Boolean,
 95 │         limits: DecodeLimits = DecodeLimits(),
 96 │     ): ConversionResult {
 97 │         val bytes = try {
 98 │             PortableSettingsCodec.encode(ready.settings)
 99 │         } catch (failure: IllegalArgumentException) {
100 │             return ConversionResult.Failed(ConversionFailure.SELF_CHECK_FAILED)
101 │         }
102 │         val decoded = (PortableSettingsCodec.decode(bytes, limits) as? DecodeResult.Valid)?.settings
103 │             ?: return ConversionResult.Failed(ConversionFailure.SELF_CHECK_FAILED)
104 │         val configuration = decoded.configuration
105 │         if (!PortableSettingsCodec.encode(decoded).contentEquals(bytes)) return ConversionResult.Failed(ConversionFailure.SELF_CHECK_FAILED)
106 │         validator.firstProblem(configuration)?.let { return ConversionResult.Failed(ConversionFailure.SELF_CHECK_FAILED, "${it.store}/${it.key}") }
107 │         for ((store, values) in listOf(SettingsStoreId.SHARED_PREFERENCES to configuration.sharedPreferences, SettingsStoreId.DATA_STORE to configuration.dataStore)) {
108 │             for ((key, value) in values) {
109 │                 val disposition = SettingsCatalog.dispositionOf(store, key)
110 │                 if (disposition !is SettingDisposition.Configuration || disposition.type != value.type) {
111 │                     return ConversionResult.Failed(ConversionFailure.SELF_CHECK_FAILED, "$store/$key")
112 │                 }
113 │             }
114 │         }
115 │         val preview = ExportPreview(
116 │             source = decoded.source,
117 │             versionKnown = versionKnown,
118 │             sharedPreferenceCount = configuration.sharedPreferences.size,
119 │             dataStoreCount = configuration.dataStore.size,
120 │             appRowCount = configuration.rows.apps.size,
121 │             timeLimitCount = configuration.rows.timeLimits.size,
122 │             widgetProfileCount = widgetProfileCount,
123 │             unsupported = decoded.unsupportedKeys,
124 │             omitted = ready.report.omitted.sortedWith(compareBy({ it.store }, { it.key })),
125 │         )
126 │         return ConversionResult.Ready(bytes, preview)
127 │     }
128 │ }

