100 │ private class FrameworkTransactions(private val database: SQLiteDatabase) : SqlTransactionRunner {
101 │     override fun <T> inTransaction(block: (SqlSession) -> T): T {
102 │         database.beginTransaction()
103 │         try {
104 │             val result = block(object : SqlSession {
105 │                 override fun query(sql: String, args: List<Any?>): List<List<Any?>> =
106 │                     database.rawQuery(sql, args.map { it?.toString() }.toTypedArray()).use { cursor ->
107 │                         buildList {
108 │                             while (cursor.moveToNext()) add((0 until cursor.columnCount).map { index ->
109 │                                 when (cursor.getType(index)) {
110 │                                     android.database.Cursor.FIELD_TYPE_NULL -> null
111 │                                     android.database.Cursor.FIELD_TYPE_INTEGER -> cursor.getLong(index)
112 │                                     android.database.Cursor.FIELD_TYPE_STRING -> cursor.getString(index)
113 │                                     else -> throw IllegalStateException("unexpected column type")
114 │                                 }
