119 │                 // The helper never writes to even its own copy.
120 │                 override fun execute(sql: String, args: List<Any?>) = throw UnsupportedOperationException("read-only session")
121 │             })
122 │             database.setTransactionSuccessful()
123 │             return result
124 │         } finally {
125 │             database.endTransaction()
